 sections=[
  ("risques", "Les risques majeurs des îles du Nord", """<p>Saint-Martin et Saint-Barthélemy, situées au nord de l'arc antillais, sont exposées aux <strong>cyclones tropicaux</strong> de juin à novembre. L'ouragan <strong>Irma</strong>, en septembre 2017, a causé des dégâts majeurs sur les deux îles. S'y ajoutent :</p><ul class="check"><li>Le <strong>risque sismique</strong> de l'arc des Petites Antilles, avec un risque de <strong>tsunami</strong> en zone littorale, d'autant plus important que tout le bâti est proche de la mer.</li><li>Les <strong>inondations</strong> et les vagues de surcote lors des tempêtes.</li><li>Les <strong>restrictions de ressources</strong> : les deux îles dépendent largement de l'importation pour l'alimentation, l'eau en bouteille et les carburants. Un avion en mer met les approvisionnements en pause pendant plusieurs jours.</li></ul><p>Consultez les risques sur <a href="https://www.georisques.gouv.fr" rel="noopener">georisques.gouv.fr</a>.</p>"""),
  ("kit", "Un kit 72 h à la sauce insulaire", """<p>Le socle, encore : au moins 6 litres d'eau par personne pour 3 jours (davantage par forte chaleur), aliments sans cuisson, radio à piles, lampe, batterie externe, trousse de secours, documents dans une pochette étanche. Mais sur deux si petites îles, l'autonomie doit aller plus loin :</p><ul class="check"><li><strong>Une semaine de provisions minimum</strong> si l'entreposage le permet : les réapprovisionnements maritimes prennent du temps après un ouragan majeur.</li><li>Matériel anti-vent : bâches, ruban adhésif, cordes, claquages pour refaire temporairement de l'étanchéité.</li><li>Écharpe réflexe : identifier son point de regroupement hors zone littorale en cas de tsunami.</li><li>Évidence d'hydratation : en zone tropicale, manquer d'eau se dégrade vite. Voir <a href="combien-eau-stocker-par-personne.html">combien d'eau stocker</a>.</li></ul>"""),
  ("alerte", "Où suivre les alertes officielles", """<ul class="check"><li><strong>Météo-France Antilles-Guyane</strong> pour les vigilances cycloniques et fortes pluies.</li><li><a href="https://www.saint-barth-saint-martin.gouv.fr" rel="noopener">Préfecture de Saint-Barthélemy et de Saint-Martin</a> pour les consignes et décisions préfectorales.</li><li><strong>FR-Alert</strong> sur mobile, voir <a href=\"fr-alert-que-faire.html\">FR-Alert : que faire</a>.</li><li>Collectivités et radio : les médias locaux restent les premières sources d'info en cas de panne du réseau mobile.</li></ul>"""),
  ("reflexes", "Les réflexes clés des îles du Nord", """<ol class="steps-list"><li>Dès juin : revue annuelle du kit, vérification des profilés anti-vent, réserves d'eau et de carburant.</li><li>En vigilance orange cyclone : tout immobiliser, charger téléphones, refaire le plein d'eau.</li><li>En vigilance rouge : confinement total, aucun déplacement.</li><li>Séisme ressenti en zone littorale : dès que le tremblement s'arrête, gagner immédiatement les hauteurs sans attendre de confirmation, c'est le réflexe anti-tsunami universel.</li></ol><p>Les cyclones post-Irma ont pulvérisé les infrastructures sur ces deux Îsles : préparer le <a href="kit-urgence-72h-famille-appartement-voiture.html">kit pour la famille</a> relève de l'évidence.</p>"""),
 ],
